ROOT=Path('/Users/mohammed.awad/Documents/Codex/2026-09-19/c');OUT=ROOT/'outputs/ph_analysis'
read=lambda p:json.loads((OUT/p).read_text())
rows=read('layer_metrics.json');selections=read('selections.json');phases=read('phase_summaries.json')
